// Normaliza saída do classifier para tokens válidos
const raw = ($input.first().json.output || '').toString().toUpperCase().trim();
const valid = ['TASKS','FINANCES','HOUSE','PROFILE','DEVICES','GENERAL','OUT_OF_SCOPE'];
const found = valid.find(v => raw.includes(v)) || 'OUT_OF_SCOPE';
const ctx = $('Extract Context').item.json;
return { json: { ...ctx, intent: found } };

const raw = ($input.first().json.output || '').toString();
// Remove function-call leftovers
let clean = raw.replace(/<function[^>]*>.*?<\/function>/gis, '');
clean = clean.replace(/\{[^}]*"input"[^}]*\}/gi, '');
clean = clean.replace(/\s+/g, ' ').trim();
clean = clean.replace(/\s+([.,!?])/g, '$1');
if (!clean || clean.length < 2) clean = raw;
// Detecta delegação inválida do specialist
if (/DELEGATE:OUT_OF_DOMAIN/i.test(clean)) {
  clean = 'Posso ajudar com tarefas, finanças, gestão da casa, perfil e dispositivos. Para outros assuntos, prefiro não responder para manter o foco. 😊';
}
const ctx = $('Extract Context').item.json;
return { json: { success: true, response: clean, metadata: { session_id: ctx.session_id, intent: $('Normalize Intent').item.json.intent, message_id: ctx.message_id, model: 'gemini-2.0-flash' } } };
